{"implementation": "def solve(case):
    nodes = case["nodes"]
    required_symbols = set(case["required_symbols"])

    # Validate required fields
    for node in nodes:
        for field in ("id", "parent", "symbol", "depth", "removable", "utility"):
            if field not in node:
                raise ValueError(f"Node missing required field '{field}'")

    node_map = {n["id"]: n for n in nodes}
    children = {n["id"]: [] for n in nodes}

    roots = [n for n in nodes if n["parent"] is None]
    if not roots:
        raise ValueError("No root node found")
    if len(roots) > 1:
        raise ValueError("Multiple root nodes found")

    for n in nodes:
        if n["parent"] is not None:
            if n["parent"] not in node_map:
                raise ValueError(f"Parent '{n['parent']}' not in node set for node '{n['id']}'")
            children[n["parent"]].append(n["id"])

    # Current retained set
    retained = set(n["id"] for n in nodes)

    # Count retained nodes per symbol
    symbol_count = {}
    for n in nodes:
        sym = n["symbol"]
        symbol_count[sym] = symbol_count.get(sym, 0) + 1

    # Process order: deepest first, then lexicographic node ID as stable tie-break
    sorted_nodes = sorted(nodes, key=lambda n: (-n["depth"], n["id"]))

    removed_order = []

    for node in sorted_nodes:
        nid = node["id"]

        # Must be explicitly marked removable
        if not node["removable"]:
            continue

        # Never remove root
        if node["parent"] is None:
            continue

        # Never remove a node that still has retained children
        if any(c in retained for c in children[nid]):
            continue

        # Never remove if it would eliminate coverage of a required symbol
        sym = node["symbol"]
        if sym in required_symbols and symbol_count.get(sym, 0) <= 1:
            continue

        # Tentative removal passes all checks — commit it
        retained.discard(nid)
        symbol_count[sym] -= 1
        removed_order.append(nid)

    return {
        "removed_node_ids": removed_order,
        "retained_node_ids": sorted(retained)
    }
"}
